class MahjongConnect:
    """
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    """

    def __init__(self, BOARD_SIZE, ICONS):
        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()

    def create_board(self):
        rows, cols = self.BOARD_SIZE
        total_cells = rows * cols
        # Fill board with pairs of icons
        flat_list = []
        for i in range(total_cells // 2):
            icon = self.ICONS[i % len(self.ICONS)]
            flat_list.extend([icon, icon])
        random.shuffle(flat_list)

        board = []
        for r in range(rows):
            board.append(flat_list[r * cols : (r + 1) * cols])
        return board

    def is_valid_move(self, pos1, pos2):
        r1, c1 = pos1
        r2, c2 = pos2
        rows, cols = self.BOARD_SIZE

        # Check bounds
        if not (0 <= r1 < rows and 0 <= c1 < cols and 0 <= r2 < rows and 0 <= c2 < cols):
            return False
        # Check if same position
        if pos1 == pos2:
            return False
        # Check if icons match and are not empty
        if self.board[r1][c1] == ' ' or self.board[r1][c1] != self.board[r2][c2]:
            return False

        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        """
        Simple pathfinding: checks for paths with at most 2 turns (standard Mahjong Connect rule).
        """
        r1, c1 = pos1
        r2, c2 = pos2
        rows, cols = self.BOARD_SIZE

        def is_empty(r, c):
            return 0 <= r < rows and 0 <= c < cols and self.board[r][c] == ' '

        # Check direct line (0 turns)
        if r1 == r2:
            if all(is_empty(r1, c) for c in range(min(c1, c2) + 1, max(c1, c2))): return True
        if c1 == c2:
            if all(is_empty(r, c1) for r in range(min(r1, r2) + 1, max(r1, r2))): return True

        # Check 1 turn
        corners = [(r1, c2), (r2, c1)]
        for cr, cc in corners:
            if self.board[cr][cc] == ' ':
                if self.has_path(pos1, (cr, cc)) and self.has_path((cr, cc), pos2):
                    return True
        return False

    def remove_icons(self, pos1, pos2):
        self.board[pos1[0]][pos1[1]] = ' '
        self.board[pos2[0]][pos2[1]] = ' '

    def is_game_over(self):
        for row in self.board:
            for cell in row:
                if cell != ' ':
                    return False
        return True

class MetricsCalculator:
    """
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    """

    def __init__(self):
        """
        Initialize the number of all four samples to 0
        """
        self.true_positives = 0
        self.false_positives = 0
        self.false_negatives = 0
        self.true_negatives = 0

    def update(self, predicted_labels, true_labels):
        """
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        """
        for pred, true in zip(predicted_labels, true_labels):
            if pred == 1 and true == 1:
                self.true_positives += 1
            elif pred == 1 and true == 0:
                self.false_positives += 1
            elif pred == 0 and true == 1:
                self.false_negatives += 1
            elif pred == 0 and true == 0:
                self.true_negatives += 1

    def precision(self, predicted_labels, true_labels):
        """
        Calculate precision
        """
        self.update(predicted_labels, true_labels)
        if (self.true_positives + self.false_positives) == 0:
            return 0.0
        return self.true_positives / (self.true_positives + self.false_positives)

    def recall(self, predicted_labels, true_labels):
        """
        Calculate recall
        """
        self.update(predicted_labels, true_labels)
        if (self.true_positives + self.false_negatives) == 0:
            return 0.0
        return self.true_positives / (self.true_positives + self.false_negatives)

    def f1_score(self, predicted_labels, true_labels):
        """
        Calculate f1 score, which is the harmonic mean of precision and recall
        """
        p = self.precision(predicted_labels, true_labels)
        r = self.recall(predicted_labels, true_labels)
        if (p + r) == 0:
            return 0.0
        return 2 * (p * r) / (p + r)

    def accuracy(self, predicted_labels, true_labels):
        """
        Calculate accuracy
        """
        self.update(predicted_labels, true_labels)
        total = self.true_positives + self.false_positives + self.false_negatives + self.true_negatives
        if total == 0:
            return 0.0
        return (self.true_positives + self.true_negatives) / total

